"""Notice-period computer for contract terminations.

Implements the Corbin convention for month arithmetic:
the same day-of-month in the target month, clamped to the LAST day
of the target month when that day does not exist.
"""

import calendar
import re
from datetime import date, timedelta

_NOTICE_RE = re.compile(r"\s*(\d+)\s+(day|days|week|weeks|month|months)\s*")


def _parse(notice: str) -> tuple[int, str]:
    m = _NOTICE_RE.fullmatch(notice)
    if not m:
        raise ValueError(f"invalid notice period: {notice!r}")
    n = int(m.group(1))
    unit = m.group(2)
    return n, unit.rstrip("s")


def _clamp_day(year: int, month: int, day: int) -> date:
    """Corbin convention: clamp day to the last day of the month."""
    last = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last))


def _shift_months(d: date, n: int) -> date:
    total = d.month - 1 + n
    year = d.year + total // 12
    month = total % 12 + 1
    return _clamp_day(year, month, d.day)


def effective_date(sent: date, notice: str) -> date:
    """Date on which a termination sent on `sent` with period `notice` takes effect."""
    n, unit = _parse(notice)
    if unit == "day":
        return sent + timedelta(days=n)
    if unit == "week":
        return sent + timedelta(weeks=n)
    return _shift_months(sent, n)


def latest_send_date(deadline: date, notice: str) -> date:
    """Latest date the notice can be sent to be effective on or before `deadline`.

    Exact inverse of `effective_date` where possible; handles the month-end
    asymmetry of the Corbin convention explicitly.
    """
    n, unit = _parse(notice)

    if unit == "day":
        result = deadline - timedelta(days=n)
    elif unit == "week":
        result = deadline - timedelta(weeks=n)
    else:
        # Start from the naive inverse (subtract n months, clamped), then push
        # as late as possible within that month: any later *month* would land
        # in a month beyond the deadline's target month, so the answer lies
        # in the month of the naive inverse.
        candidate = _shift_months(deadline, -n)
        result = candidate
        last_day = calendar.monthrange(candidate.year, candidate.month)[1]
        for day in range(last_day, candidate.day, -1):
            probe = date(candidate.year, candidate.month, day)
            if effective_date(probe, notice) <= deadline:
                result = probe
                break

    assert effective_date(result, notice) <= deadline, (
        f"{notice} sent {result} must be effective on or before {deadline}"
    )
    assert effective_date(result + timedelta(days=1), notice) > deadline, (
        f"{notice} sent {result + timedelta(days=1)} must NOT be effective "
        f"on or before {deadline}"
    )
    return result

